import {collectSymbols,suggestions,expandSnippet,signatureAt} from './assist-core.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function setupAssist(code){
 const menu=document.createElement('div');menu.className='completion-menu';menu.hidden=true;menu.id='sclCompletion';menu.setAttribute('role','listbox');menu.setAttribute('aria-label','Podpowiedzi kodu SCL');document.body.append(menu);
 const signature=document.createElement('div');signature.className='signature-hint';signature.hidden=true;document.body.append(signature);
 code.setAttribute('aria-autocomplete','list');code.setAttribute('aria-controls',menu.id);code.setAttribute('aria-expanded','false');
 let active=null,selected=0,session=null,changing=false,beforeEdit=null,cache=null,cacheSource='',cacheGlobals='',cacheMachine=null,timer,lastOptions={};
 function symbols(){const source=code.value,globals=document.querySelector('#globalsJson')?.value||'{}',machine=window.SCLLab?.machine;if(cacheSource!==source||cacheGlobals!==globals||cacheMachine!==machine||!cache){cacheSource=source;cacheGlobals=globals;cacheMachine=machine;cache=collectSymbols(source,machine,globals);}return cache;}
 function coordinates(){const styles=getComputedStyle(code),mirror=document.createElement('div');mirror.style.cssText='position:fixed;left:-9999px;top:0;visibility:hidden;white-space:pre;overflow:visible;';for(const prop of ['fontFamily','fontSize','fontWeight','lineHeight','letterSpacing','tabSize','paddingLeft','paddingTop','borderLeftWidth','borderTopWidth'])mirror.style[prop]=styles[prop];mirror.textContent=code.folding?.prefix()??code.value.slice(0,code.selectionStart);const span=document.createElement('span');span.textContent='\u200b';mirror.append(span);document.body.append(mirror);const rect=code.getBoundingClientRect(),x=rect.left+span.offsetLeft-code.scrollLeft,y=rect.top+span.offsetTop-code.scrollTop,h=parseFloat(styles.lineHeight)||24;mirror.remove();return {x,y,h,rect};}
 function position(el,height){const c=coordinates();const width=Math.min(430,innerWidth-24);el.style.width=width+'px';el.style.left=Math.max(8,Math.min(c.x,innerWidth-width-10))+'px';const below=c.y+c.h+4;el.style.top=(below+height>innerHeight-12?Math.max(48,c.y-height-4):Math.max(48,below))+'px';}
 function close(){active=null;menu.hidden=true;code.setAttribute('aria-expanded','false');code.removeAttribute('aria-activedescendant');}
 function draw(){if(!active)return;menu.innerHTML='<div class="completion-heading"><span>PODPOWIEDZI SCL</span><kbd>Ctrl+Space</kbd></div><div class="completion-items">'+active.items.map((item,i)=>`<div class="completion-item ${i===selected?'selected':''}" role="option" aria-selected="${i===selected}" id="scl-option-${i}" data-index="${i}"><span class="completion-icon ${item.kind==='szablon'?'snippet':''}">${item.kind==='szablon'?'{}':item.kind==='zmienna'?'v':item.kind==='pole'?'.':'ƒ'}</span><span class="completion-label">${esc(item.label)}</span><small>${esc(item.kind)}</small></div>`).join('')+'</div><div class="completion-description">'+esc(active.items[selected]?.detail||'')+'</div><div class="completion-footer">↑ ↓ wybór <span>Enter / Tab wstaw</span><span>Esc zamknij</span></div>';menu.hidden=false;code.setAttribute('aria-expanded','true');code.setAttribute('aria-activedescendant','scl-option-'+selected);position(menu,Math.min(330,active.items.length*30+102));menu.querySelector('.selected')?.scrollIntoView({block:'nearest'});}
 function refresh(options={}){lastOptions=options;if(code.selectionStart!==code.selectionEnd&&!options.manual){close();return;}active=suggestions(code.value,code.selectionStart,symbols(),options);selected=0;if(active){draw();signature.hidden=true;}else{close();const text=signatureAt(code.value,code.selectionStart,symbols());signature.textContent=text||'';signature.hidden=!text;if(text)position(signature,54);}}
 function inputEvent(){code.dispatchEvent(new Event('input',{bubbles:true}));}
 function accept(){if(!active)return false;const chosen=active.items[selected];const fresh=suggestions(code.value,code.selectionStart,symbols(),lastOptions);if(!fresh){close();return false;}const item=fresh.items.find(i=>i.label===chosen.label&&i.kind===chosen.kind)||fresh.items[0],range=fresh;const indent=code.value.slice(0,range.start).split('\n').at(-1).match(/^\s*/)?.[0]||'';const result=item.snippet?expandSnippet(item.insert,indent):{text:item.insert,stops:[]};changing=true;code.setRangeText(result.text,range.start,range.end,'end');close();signature.hidden=true;session=result.stops.length?{stops:result.stops.map(s=>({...s,start:s.start+range.start,end:s.end+range.start})),at:0}:null;if(session){const s=session.stops[0];code.setSelectionRange(s.start,s.end);}inputEvent();changing=false;code.focus();return true;}
 function gotoStop(direction){if(!session)return false;const next=session.at+direction;if(next<0||next>=session.stops.length){session=null;return false;}session.at=next;const s=session.stops[next];close();code.setSelectionRange(s.start,s.end);if(s.index===0)session=null;return true;}
 menu.addEventListener('mousedown',e=>{const item=e.target.closest('[data-index]');if(!item)return;e.preventDefault();selected=Number(item.dataset.index);accept();});
 code.addEventListener('beforeinput',()=>{beforeEdit={start:code.selectionStart,end:code.selectionEnd,length:code.value.length};});
 code.addEventListener('input',()=>{if(changing)return;if(session&&beforeEdit){const stop=session.stops[session.at],delta=code.value.length-beforeEdit.length;if(beforeEdit.start>=stop.start&&beforeEdit.end<=stop.end){stop.end+=delta;for(let i=session.at+1;i<session.stops.length;i++){session.stops[i].start+=delta;session.stops[i].end+=delta;}}else session=null;}beforeEdit=null;clearTimeout(timer);timer=setTimeout(()=>refresh(),60);});
 code.addEventListener('keydown',e=>{
  const stop=()=>{e.preventDefault();e.stopImmediatePropagation();};
  if((e.ctrlKey||e.metaKey)&&e.code==='Space'){stop();refresh({manual:true});return;}
  if(active){if(e.key==='ArrowDown'||e.key==='ArrowUp'){stop();selected=(selected+(e.key==='ArrowDown'?1:-1)+active.items.length)%active.items.length;draw();return;}if(e.key==='Enter'||e.key==='Tab'){if(accept()){stop();return;}}if(e.key==='Escape'){stop();close();return;}if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key))close();}
  if(e.key==='Escape'){close();session=null;signature.hidden=true;return;}
  if(e.key==='Tab'&&session){stop();if(!gotoStop(e.shiftKey?-1:1))session=null;return;}
  const pairs={'(':')','[':']',"'":"'",'"':'"'};
  if(!e.ctrlKey&&!e.metaKey&&!e.altKey&&Object.hasOwn(pairs,e.key)){
   stop();const start=code.selectionStart,end=code.selectionEnd,selectedText=code.value.slice(start,end),closing=pairs[e.key];if(start===end&&code.value[start]===e.key&&(e.key==='"'||e.key==="'")){code.setSelectionRange(start+1,start+1);return;}
   changing=true;code.setRangeText(e.key+selectedText+closing,start,end,'end');code.setSelectionRange(start+1,start+1+selectedText.length);session=null;inputEvent();changing=false;refresh();return;
  }
  if([')',']'].includes(e.key)&&code.selectionStart===code.selectionEnd&&code.value[code.selectionStart]===e.key){stop();code.setSelectionRange(code.selectionStart+1,code.selectionStart+1);refresh();return;}
  if(e.key==='Enter'&&!e.ctrlKey&&!e.metaKey){stop();const start=code.selectionStart,end=code.selectionEnd,before=code.value.slice(0,start).split('\n').at(-1),after=code.value.slice(end).split('\n')[0];let indent=before.match(/^\s*/)?.[0]||'';const opens=/\b(?:THEN|ELSE|DO|OF|REPEAT|BEGIN|STRUCT)\s*$/i.test(before)||/^\s*(?:\d+\s*[:,])/.test(before);const closes=/^\s*END_(?:IF|FOR|CASE|WHILE|REPEAT|STRUCT)\b/i.test(after);let text='\n'+indent+(opens?'    ':'');if(opens&&closes)text+='\n'+indent;changing=true;code.setRangeText(text,start,end,'end');const caret=start+1+indent.length+(opens?4:0);code.setSelectionRange(caret,caret);session=null;inputEvent();changing=false;close();return;}
 },true);
 code.addEventListener('click',()=>{close();signature.hidden=true;if(session){const s=session.stops[session.at];if(code.selectionStart<s.start||code.selectionStart>s.end)session=null;}});
 code.addEventListener('blur',()=>{setTimeout(()=>{close();signature.hidden=true;},100);});
 code.addEventListener('scroll',()=>{if(active)position(menu,menu.offsetHeight);if(!signature.hidden)position(signature,signature.offsetHeight);});
 window.addEventListener('resize',close);window.addEventListener('scl-layout',()=>{close();signature.hidden=true;});
 const snippetsButton=document.querySelector('#snippetsBtn');if(snippetsButton)snippetsButton.onclick=()=>{code.focus();refresh({manual:true,snippetsOnly:true});};
}
